import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1788283445000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Everything is configured through environment variables. There is no config file.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>LINKWARDEN_URL</code></td><td>yes</td><td>—</td><td>Base URL, e.g. <code>https://links.example.net</code> — <strong>without</strong> <code>/api/v1</code></td></tr><tr><td><code>LINKWARDEN_TOKEN</code></td><td>yes</td><td>—</td><td>Access token from Settings → Access Tokens</td></tr><tr><td><code>LINKWARDEN_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the 11 read tools</td></tr><tr><td><code>LINKWARDEN_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates, for this connection only</td></tr></tbody></table><p>The full reference with formats is in <a href="/reference/environment">Environment variables</a>.</p><h2 id="linkwarden-url" tabindex="-1"><code>LINKWARDEN_URL</code> <a class="header-anchor" href="#linkwarden-url" aria-label="Permalink to “LINKWARDEN_URL”">​</a></h2><p>The base URL of the instance. A trailing slash is stripped, and a URL that already carries <code>/api/v1</code> is normalised — the client appends the prefix itself, and since redirects are never followed the resulting 308 would otherwise be an opaque failure.</p><p>The server refuses to start if the URL:</p><ul><li>does not parse,</li><li>uses a scheme other than <code>http:</code> or <code>https:</code>,</li><li>contains credentials (<code>https://user:pw@…</code>) — use <code>LINKWARDEN_TOKEN</code> instead.</li></ul><p>It warns, but continues, when the URL is plain <code>http:</code> to a non-loopback host: the token would travel unencrypted.</p><h2 id="linkwarden-token" tabindex="-1"><code>LINKWARDEN_TOKEN</code> <a class="header-anchor" href="#linkwarden-token" aria-label="Permalink to “LINKWARDEN_TOKEN”">​</a></h2><p>The access token. It is <strong>deleted from the process environment</strong> as soon as it has been read, so it is not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code>.</p><p>Linkwarden&#39;s tokens are NextAuth JWTs and start with <code>ey</code>. A value that does not gets a warning at startup — usually it means a session cookie or a password was pasted in by mistake, and the warning arrives before the first confusing 401.</p><h2 id="linkwarden-read-only" tabindex="-1"><code>LINKWARDEN_READ_ONLY</code> <a class="header-anchor" href="#linkwarden-read-only" aria-label="Permalink to “LINKWARDEN_READ_ONLY”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">LINKWARDEN_READ_ONLY</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span></span></code></pre></div><p>The 17 write tools are <strong>not registered at all</strong> — they do not appear in <code>tools/list</code>. This is a stronger guarantee than refusing them at call time: a model cannot ask for a tool it cannot see, so nothing depends on the model respecting an instruction.</p><p>Worth pairing with a Linkwarden account that only has read access to the collections it is shared into, so the restriction holds on both ends.</p><h2 id="turning-the-approval-dialog-off" tabindex="-1">Turning the approval dialog off <a class="header-anchor" href="#turning-the-approval-dialog-off" aria-label="Permalink to “Turning the approval dialog off”">​</a></h2><p>The destructive tools ask a person through MCP elicitation before they act. <code>ELICITATION=false</code> takes them to the two-call token instead. It does not remove the guard; there is no setting in which a guarded call goes unannounced.</p><p>The variable deliberately carries no <code>LINKWARDEN_</code> prefix, which means it reaches every MCP server in the same environment, and — unlike the booleans here — a value it does not recognise <strong>stops the server</strong> rather than failing off. See <a href="/guide/approval">Asking a person</a>.</p><h2 id="choosing-the-tools-that-load" tabindex="-1">Choosing the tools that load <a class="header-anchor" href="#choosing-the-tools-that-load" aria-label="Permalink to “Choosing the tools that load”">​</a></h2><p>Read-only mode is one cut, along a line this server drew for you. <code>LINKWARDEN_ALLOW_TOOLS</code> and <code>LINKWARDEN_DENY_TOOLS</code> let you draw your own:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">LINKWARDEN_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">essential</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">LINKWARDEN_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">search_links,get_link_content,create_link</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">LINKWARDEN_DENY_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">bulk_*</span></span></code></pre></div><p>Why bother, when all twenty-eight work: a model chooses the right tool far more reliably from a handful than from a long list, and every tool it can see costs context on every single request. If this is the only MCP server in a session, twenty-eight is fine. If it is one of six, it is not.</p><p><strong>The syntax.</strong> Comma-separated entries. An entry is either an exact tool name or a prefix with a trailing <code>*</code> — <code>list_*</code> matches every tool whose name starts with <code>list_</code>. Entries are trimmed and case-insensitive, empty ones are ignored, and an empty value counts as unset. Nothing else is a pattern: <code>*_link</code> and <code>list_*_x</code> are rejected rather than silently matching nothing.</p><p><strong><code>essential</code></strong> is a curated preset of eight — save, find, read:</p><p><code>search_links</code> · <code>get_link</code> · <code>get_link_content</code> · <code>list_collections</code> · <code>list_tags</code> · <code>create_link</code> · <code>update_link</code> · <code>delete_link</code></p><p><code>get_link_content</code> is in it because the preserved article text is the actual reason to point a model at Linkwarden. Left out on purpose: <code>bulk_update_links</code> and <code>bulk_delete_links</code>, which are footguns by design; the preservation-queue admin tools; RSS subscriptions; and collection and tag CRUD. The preset is marked per tool in the <a href="/reference/tools">tool reference</a>, generated from the same constant the filter reads, so the two cannot drift.</p><p>It composes — <code>essential,get_dashboard</code> adds one back, and <code>LINKWARDEN_DENY_TOOLS</code> takes one away.</p><p><strong>Both together.</strong> <code>LINKWARDEN_ALLOW_TOOLS</code> decides what is in; <code>LINKWARDEN_DENY_TOOLS</code> is then subtracted from the result. With only a deny list, everything else stays.</p><p><strong>A name that matches nothing stops the server</strong>, with the offending entry and the list of real names. That is deliberate: the alternative is a tool quietly missing from <code>tools/list</code>, and nobody traces an absence back to an environment variable. The same applies to a pattern that matches no tool, which is what catches <code>delet_*</code>.</p><p><strong>With read-only mode</strong>, the write tools are not registered at all, so naming one explicitly in <code>LINKWARDEN_ALLOW_TOOLS</code> is an error that says so — rather than calling a tool unknown when it plainly exists. A <em>pattern</em> that covers write tools is fine and simply contributes nothing, which is what makes <code>get_*,create_*</code> a usable template for both kinds of deployment; and <code>LINKWARDEN_ALLOW_TOOLS=essential</code> narrows to the read half of the preset.</p><div class="tip custom-block"><p class="custom-block-title">It is the same cut, not a second one</p><p>A filtered tool is never registered, so it is absent from <code>tools/list</code> and unknown to <code>tools/call</code> alike — exactly what <code>LINKWARDEN_READ_ONLY</code> does to a write tool. There is no &quot;hidden but callable&quot; state to reason about.</p></div><h2 id="linkwarden-insecure-tls" tabindex="-1"><code>LINKWARDEN_INSECURE_TLS</code> <a class="header-anchor" href="#linkwarden-insecure-tls" aria-label="Permalink to “LINKWARDEN_INSECURE_TLS”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">LINKWARDEN_INSECURE_TLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span></span></code></pre></div><p>Accepts self-signed certificates. This is a <strong>scoped undici dispatcher</strong>, not <code>NODE_TLS_REJECT_UNAUTHORIZED</code> — certificate validation stays on for everything else in the process.</p><p>Prefer a proper internal CA. If your instance runs on an internal domain with a private CA, adding that CA to the trust store (or <code>NODE_EXTRA_CA_CERTS</code>) keeps validation intact and is barely more work.</p><h2 id="only-the-exact-string-true" tabindex="-1">Only the exact string <code>true</code> <a class="header-anchor" href="#only-the-exact-string-true" aria-label="Permalink to “Only the exact string true”">​</a></h2><p>All boolean flags are compared against the literal string <code>true</code>. <code>True</code>, <code>1</code> and <code>yes</code> are all off. A typo therefore cannot silently disable certificate validation — it fails closed.</p>`,38)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};